def factorial(n):
    """
    Returns the factorial of the given number n using recursion.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def longest_common_subsequence(s1: str, s2: str) -> int:
    """
    Returns the length of the longest common subsequence between two strings s1 and s2.
    """
    n = len(s1)
    m = len(s2)

    # Create a 2D array to store lengths of longest common subsequence.
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][m]

