def is_complete_binary_tree(tree):
    """
    Determines if the given binary tree (represented as a level order list of elements)
    is a Complete Binary Tree.
    """
    if not tree:
        return True

    n = len(tree)

    # Identify the first occurrence of None
    for i in range(n):
        if tree[i] is None:
            # Check if all the elements after the first None are also None
            for j in range(i, n):
                if tree[j] is not None:
                    return False
            break

    return True

