from typing import List

def house_robber(houses: List[int]) -> int:
    if not houses:
        return 0
    elif len(houses) == 1:
        return houses[0]

    previous_two = houses[0]
    previous_one = max(houses[0], houses[1])

    for i in range(2, len(houses)):
        current = max(previous_one, previous_two + houses[i])
        previous_two = previous_one
        previous_one = current

    return previous_one

