def product_or_sum(lst):
    """
    Returns the product of all elements in the list if any element is even,
    and the sum of all elements if all elements are odd.

    Parameters:
    lst (list): A list of integers.

    Returns:
    int: The product if any element is even, otherwise the sum.
    """
    if any(x % 2 == 0 for x in lst):
        product = 1
        for num in lst:
            product *= num
        return product
    else:
        return sum(lst)

def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string that can be achieved
    by repeatedly reversing any two-character substring in the input string s.
    """
    # Convert string to list for in-place manipulation
    s = list(s)

    # We can use a simple greedy approach by continually sorting the string
    n = len(s)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if s[j] > s[j + 1]:
                # Swap adjacent characters if they are in wrong order
                s[j], s[j + 1] = s[j + 1], s[j]

    # Join the list back into a string
    return ''.join(s)

def rotate_matrix(matrix):
    """
    Rotates the given NxN matrix 90 degrees clockwise in place.
    """
    n = len(matrix)
    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # Reverse each row
    for i in range(n):
        matrix[i].reverse()

