def fibonacci(n):
    """
    Returns the nth Fibonacci number. If the input is negative, returns an error message.
    """
    if not isinstance(n, int) or n < 0:
        return "Input should be a non-negative integer"

    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

def longest_valid_parentheses(s):
    """
    Returns the length of the longest valid parentheses substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with a base for the next valid substring

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

