def most_common_element(lst):
    """
    Returns the most common element in the list. If there are multiple elements with the same highest frequency,
    returns the one that appears first. If the list is empty, returns None.
    """
    if not lst:
        return None

    element_count = {}
    max_count = 0
    most_common = None

    for element in lst:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

        if element_count[element] > max_count:
            max_count = element_count[element]
            most_common = element

    return most_common

