from functools import reduce

def gcd_of_list(numbers: list) -> int:
    """
    Returns the greatest common divisor (GCD) of a list of positive integers.
    If the list is empty, return None.
    """
    if not numbers:
        return None

    return reduce(math.gcd, numbers)

