from typing import List, Dict, Any

def analyze_data(data: List[Dict[str, Any]]) -> Dict[str, Any]:
    total_value_per_category = {}
    unique_tags = set()
    highest_value_item = None

    for item in data:
        category, name, value, tags = item['category'], item['name'], item['value'], item['tags']

        # Calculate total value per category
        if category in total_value_per_category:
            total_value_per_category[category] += value
        else:
            total_value_per_category[category] = value

        # Collect unique tags
        unique_tags.update(tags)

        # Find item with the highest value
        if highest_value_item is None or value > highest_value_item['value']:
            highest_value_item = {"name": name, "value": value}

    return {
        "total_value_per_category": total_value_per_category,
        "unique_tags": unique_tags,
        "highest_value_item": highest_value_item
    }

