def smallest_even_number(numbers):
    """
    Returns the smallest even number from a given list of integers.
    If no even number is found, return None.
    """
    even_numbers = [num for num in numbers if num % 2 == 0]

    if not even_numbers:
        return None

    return min(even_numbers)

