def is_valid_parentheses(s):
    """
    Returns True if the string s contains valid parentheses, otherwise False.
    """
    stack = []
    matching_parentheses = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses:
            if stack == [] or matching_parentheses[char] != stack.pop():
                return False
        else:
            return False

    return stack == []

