def find_missing_letter(chars):
    """
    This function takes a list of consecutive (increasing) letters with one letter missing
    and returns the missing letter.

    :param chars: List of consecutive characters with one missing
    :type chars: list of str
    :return: The missing character
    :rtype: str
    """
    for i in range(len(chars) - 1):
        if ord(chars[i+1]) - ord(chars[i]) > 1:
            return chr(ord(chars[i]) + 1)

