def knapsack(items, weight_limit):
    # Number of items
    n = len(items)

    # Initialize a table to store the maximum value for each weight limit
    dp = [[0 for w in range(weight_limit + 1)] for i in range(n + 1)]

    # Build the table in a bottom-up manner
    for i in range(1, n + 1):
        for w in range(weight_limit + 1):
            weight, value = items[i - 1]
            if weight <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w-weight] + value)
            else:
                dp[i][w] = dp[i-1][w]

    return dp[n][weight_limit]

