def grade_text(score):
    """
    Convert a numeric score to a letter grade.

    Parameters:
    score (int): Numeric score between 0 and 100.

    Returns:
    str: Corresponding letter grade.

    Raises:
    ValueError: If score is not within the range 0 to 100.
    """
    if not (0 <= score <= 100):
        raise ValueError("Score must be between 0 and 100")

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

