def pair_elements(list1, list2):
    """
    Create a list of pairs where each pair is created by combining elements
    from the lists based on their positions.
    """
    combined_list = []

    for sublist1, sublist2 in zip(list1, list2):
        for x, y in zip(sublist1, sublist2):
            combined_list.append((x, y))

    return combined_list

