reference_solution:
def reverse_string_preserve_case(s: str) -> str:
    """
    Returns the input string reversed while preserving the case of each character as it appeared in the original string.
    """
    reversed_s = s[::-1]  # Reverse the string
    result = []

    for i in range(len(s)):
        if s[i].isupper():
            result.append(reversed_s[i].upper())
        else:
            result.append(reversed_s[i].lower())

    return ''.join(result)

def count_subarrays_with_sum(arr, t):
    """
    Returns the number of subarrays that sum up to t within the given list arr.
    """
    count = 0
    current_sum = 0
    sum_dict = {0: 1}   # Initialize with 0 sum having one count for edge cases.

    for num in arr:
        current_sum += num
        if current_sum - t in sum_dict:
            count += sum_dict[current_sum - t]
        if current_sum in sum_dict:
            sum_dict[current_sum] += 1
        else:
            sum_dict[current_sum] = 1

    return count

