def find_two_sum_indices(arr, x):
    """
    Finds two distinct indices such that the elements at these indices add up to x.

    Parameters:
    arr (list): List of unique positive integers.
    x (int): Target integer.

    Returns:
    list: List containing the two indices. Returns an empty list if no such pair exists.
    """
    index_map = {}
    for i, num in enumerate(arr):
        complement = x - num
        if complement in index_map:
            return sorted([index_map[complement], i])
        index_map[num] = i
    return []

