import re

def count_unique_words(file_name):
    word_count = {}
    with open(file_name, 'r') as file:
        for line in file:
            # Remove punctuation and convert to lowercase
            words = re.findall(r'\w+', line.lower())
            for word in words:
                if word in word_count:
                    word_count[word] += 1
                else:
                    word_count[word] = 1
    return len(word_count)

