def is_balanced(expression: str) -> bool:
    """
    Determines if the given string expression is balanced in terms of bracket types and proper nesting.
    """
    stack = []
    bracket_map = {')': '(', ']': '['}

    for char in expression:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

def power(base, exponent):
    """
    Returns the result of `base` raised to the power of `exponent`.
    Uses recursion to calculate the power.
    Handles negative exponents by returning the reciprocal of the positive exponent result.
    """
    if exponent == 0:
        return 1
    elif exponent > 0:
        return base * power(base, exponent - 1)
    else:
        return 1 / power(base, -exponent)

