reference_solution:
def find_triplet(arr, targetSum):
    """
    Returns a list of three distinct elements from the array `arr` whose sum is equal to `targetSum`.
    If no such triplet exists, returns an empty list.
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == targetSum:
                return [arr[i], arr[left], arr[right]]
            elif total < targetSum:
                left += 1
            else:
                right -= 1

    return []

