from typing import Set, Tuple

def cartesian_product(setA: Set[int], setB: Set[int]) -> Set[Tuple[int, int]]:
    """
    Returns the Cartesian product of two sets of integers.
    """
    product = set()
    for a in setA:
        for b in setB:
            product.add((a, b))
    return product

