def min_path_cost(cost):
    """
    Returns the minimum cost to reach the bottom-right cell from the top-left cell.

    :param cost: A list of lists of integers where cost[i][j] represents the cost of stepping on the cell (i, j)
    :return: Minimum cost to reach the bottom-right cell (m-1, n-1) from the top-left cell (0, 0)
    """
    if not cost or not cost[0]:
        return 0

    m, n = len(cost), len(cost[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = cost[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + cost[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + cost[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    return dp[m-1][n-1]

