def follows_pattern(pattern: str, string: str) -> bool:
    """
    Checks if the given string of words follows the specified pattern.
    """
    words = string.split()
    if len(pattern) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for char, word in zip(pattern, words):
        if char not in char_to_word:
            char_to_word[char] = word
        if word not in word_to_char:
            word_to_char[word] = char

        if char_to_word[char] != word or word_to_char[word] != char:
            return False

    return True

import heapq

def trapRainWater(matrix):
    if not matrix or not matrix[0]:
        return 0

    n, m = len(matrix), len(matrix[0])
    visited = [[False] * m for _ in range(n)]
    heap = []

    # Push all the border cells into the heap with their heights
    for i in range(n):
        for j in [0, m-1]:
            heapq.heappush(heap, (matrix[i][j], i, j))
            visited[i][j] = True
    for j in range(1, m-1):
        for i in [0, n-1]:
            heapq.heappush(heap, (matrix[i][j], i, j))
            visited[i][j] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                water_trapped += max(0, height - matrix[nx][ny])
                heapq.heappush(heap, (max(matrix[nx][ny], height), nx, ny))
                visited[nx][ny] = True

    return water_trapped

