def max_subarray_len(nums, k):
    """
    Returns the maximum length of a subarray that sums to k. 
    If there isn't one, returns 0.
    """
    sum_indices = {}
    total_sum = 0
    max_len = 0

    for i, num in enumerate(nums):
        total_sum += num

        if total_sum == k:
            max_len = i + 1
        elif (total_sum - k) in sum_indices:
            max_len = max(max_len, i - sum_indices[total_sum - k])

        if total_sum not in sum_indices:
            sum_indices[total_sum] = i

    return max_len

