from typing import List, Tuple

def can_finish_courses(courses: List[Tuple[int, int]]) -> bool:
    from collections import defaultdict, deque

    # Create the adjacency list for the graph
    graph = defaultdict(list)
    indegree = defaultdict(int)

    for course, prereq in courses:
        graph[prereq].append(course)
        indegree[course] += 1

        if prereq not in indegree:
            indegree[prereq] = 0

    # Create a queue and add all courses with no prerequisites
    queue = deque([node for node in indegree if indegree[node] == 0])

    count_of_courses_taken = 0

    while queue:
        course = queue.popleft()
        count_of_courses_taken += 1

        for next_course in graph[course]:
            indegree[next_course] -= 1
            if indegree[next_course] == 0:
                queue.append(next_course)

    if count_of_courses_taken == len(indegree):
        return True
    else:
        return False

def is_balanced(s: str) -> bool:
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    open_brackets = set(bracket_map.values())

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack[-1] != bracket_map[char]:
                return False
            stack.pop()

    return len(stack) == 0

