def fibonacci(N):
    """
    Returns the N'th term of the Fibonacci series.
    """
    if N == 0:
        return 0
    elif N == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, N+1):
        a, b = b, a + b
    return b

