def fizzbuzz(n):
    """
    Returns a list of numbers from 1 to n with multiples of 3 replaced by "Fizz",
    multiples of 5 replaced by "Buzz", and multiples of both 3 and 5 replaced by "FizzBuzz".
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(i)
    return result

