def comb_sort(arr):
    """
    Sorts a list of integers in ascending order using the Comb Sort algorithm.
    """
    if not arr:
        return arr

    n = len(arr)
    gap = n
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted = True

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False

    return arr

from typing import List, Tuple
from collections import defaultdict

def find_repeated_events(logs: List[Tuple[int, str]], window: int) -> List[str]:
    """
    This function takes a list of log entries (timestamp, eventID) and a time window,
    and returns a list of event IDs that have occurred more than once within the given
    time window.
    """
    event_timestamps = defaultdict(list)
    repeated_events = set()

    for timestamp, eventID in logs:
        event_timestamps[eventID].append(timestamp)

    for eventID, timestamps in event_timestamps.items():
        timestamps.sort()
        for i in range(1, len(timestamps)):
            if timestamps[i] - timestamps[i-1] <= window:
                repeated_events.add(eventID)
                break

    return list(repeated_events)

