def longest_common_subsequence(str1, str2):
    """
    Returns the longest common subsequence (LCS) between str1 and str2.
    """
    m = len(str1)
    n = len(str2)

    # Create a 2D array to store the lengths of longest common subsequences.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp array from the bottom up.
    for i in range(m):
        for j in range(n):
            if str1[i] == str2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # The LCS length is dp[m][n]
    lcs_length = dp[m][n]

    # Recover LCS from dp array.
    lcs = []
    while m > 0 and n > 0:
        if str1[m - 1] == str2[n - 1]:
            lcs.append(str1[m - 1])
            m -= 1
            n -= 1
        elif dp[m - 1][n] > dp[m][n - 1]:
            m -= 1
        else:
            n -= 1

    lcs.reverse()

    return ''.join(lcs)

