def isValid(s):
    """
    Determines if the input string s containing only parentheses is a valid parentheses sequence.
    """
    # Initialize the stack to keep track of opening parentheses
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return not stack

