reference_solution:
from typing import List

def find_target_index(array: List[int], target: int) -> int:
    """
    Finds the index of the target value using binary search in a sorted array.
    If the target value does not exist, returns -1.
    """
    left, right = 0, len(array) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if array[mid] == target:
            return mid
        elif array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

