from typing import List

def custom_insertion_sort(arr: List[int], threshold: int) -> List[int]:
    if len(arr) > threshold:
        return arr

    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and key < arr[j]:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key

    return arr

