reference_solution:
from typing import List

def min_jumps(arr: List[int]) -> int:
    if len(arr) <= 1:
        return 0

    jumps = 0
    current_end = 0
    farthest = 0
    for i in range(len(arr) - 1):
        farthest = max(farthest, i + arr[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
            if current_end >= len(arr) - 1:
                break

    return jumps

