def sum_and_product(a, b):
    """
    Returns a tuple containing the sum and product of a and b.
    Returns None if an exception occurs (though in this case there are no operations causing an exception).
    """
    try:
        result_sum = a + b
        result_product = a * b
        return (result_sum, result_product)
    except Exception:
        return None

