def extract_variables(file_path):
    """
    Extracts variable names and their corresponding values from a file.

    :param file_path: Path to the file containing variables and their values.
    :return: A dictionary with variable names as keys and their corresponding values as values.
    """
    variables = {}
    with open(file_path, 'r') as file:
        for line in file:
            if '=' in line:
                key, value = line.split('=', 1)
                variables[key.strip()] = value.strip()
    return variables

import math

def find_perfect_squares(numbers):
    """
    Returns a list of unique perfect squares from the input list.
    """
    perfect_squares = set()
    for num in numbers:
        if num >= 0:  # only non-negative numbers can be perfect squares
            root = int(math.isqrt(num))
            if root * root == num:
                perfect_squares.add(num)
    return sorted(perfect_squares)

