def remove_min_chars_to_unique(s):
    """
    Remove the minimum number of characters from the string s so that all the remaining characters are unique.
    Returns a resulting string with all distinct characters in their original order.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

from math import isqrt

def sum_of_prime_factors(n: int) -> int:
    if n < 2:
        raise ValueError("Input must be an integer greater than or equal to 2.")

    prime_factors = set()

    # check number of 2's that divide n
    while n % 2 == 0:
        prime_factors.add(2)
        n //= 2

    # n must be odd at this point, so skip even numbers and iterate only for odd numbers
    for i in range(3, isqrt(n) + 1, 2):
        while n % i == 0:
            prime_factors.add(i)
            n //= i

    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        prime_factors.add(n)

    return sum(prime_factors)

