def can_segment_string(s, k):
    """
    Determines if a string s can be segmented into a sequence of words each of length k
    with unique characters. If possible, returns the sequence, otherwise an empty list.
    """
    if len(s) % k != 0:
        return []

    segments = [s[i:i+k] for i in range(0, len(s), k)]

    for segment in segments:
        if len(set(segment)) != k:
            return []

    return segments

