def evaluate_expression(s):
    """
    Evaluate a mathematical expression in string format and return the result as an integer.
    """
    tokens = s.split()
    stack = []
    current = 0
    operator = '+'

    for token in tokens + ['+']:
        if token.isdigit():
            num = int(token)
            if operator == '+':
                stack.append(num)
            elif operator == '-':
                stack.append(-num)
            elif operator == '*':
                stack.append(stack.pop() * num)
            elif operator == '/':
                stack.append(int(stack.pop() / num))
        else:
            operator = token

    return sum(stack)

