reference_solution:
def tuples_to_dict(tuples_list):
    """
    Converts a list of tuples into a dictionary. If there are duplicate keys, 
    the values are aggregated into a list.

    Args:
    tuples_list (list of tuples): The input list of tuples where each tuple contains
                                  a key-value pair.

    Returns:
    dict: A dictionary with keys from the first elements of the tuples and values
          from the second elements of the tuples. Duplicate keys have values aggregated in lists.
    """
    result_dict = {}
    for key, value in tuples_list:
        if key in result_dict:
            if isinstance(result_dict[key], list):
                result_dict[key].append(value)
            else:
                result_dict[key] = [result_dict[key], value]
        else:
            result_dict[key] = value
    return result_dict

