reference_solution:
def maxGold(N, Gold):
    if N == 0:
        return 0
    elif N == 1:
        return Gold[0]

    dp = [0] * N
    dp[0] = Gold[0]
    dp[1] = max(Gold[0], Gold[1])

    for i in range(2, N):
        dp[i] = max(Gold[i] + dp[i-2], dp[i-1])

    return dp[N-1]

