def sum_of_squares(lst):
    """
    Returns the sum of squares of elements in a list if all elements are integers or floats.
    If the list contains non-integer or non-float values, it returns None.
    """
    if not all(isinstance(x, (int, float)) for x in lst):
        return None

    return sum(x**2 for x in lst)

