def maxProfit(time, profit, totalHours):
    n = len(time)
    # DP array - dp[i] will store the maximum profit that can be achieved using i hours
    dp = [0] * (totalHours + 1)

    for i in range(n):
        # Traverse backwards to ensure that each project is only considered once
        for j in range(totalHours, time[i] - 1, -1):
            dp[j] = max(dp[j], dp[j - time[i]] + profit[i])

    return dp[totalHours]

