def sum_of_squares(arr):
    """
    Returns the sum of squares of the elements in an array where elements are between 1 and n, where n is the size of the array.
    If elements are not between 1 and n, returns -1.
    """
    n = len(arr)
    for elem in arr:
        if elem < 1 or elem > n:
            return -1

    return sum(x ** 2 for x in arr)

