from typing import List

def increment_number(digits: List[int]) -> List[int]:
    n = len(digits)

    # Start from the last digit and proceed backwards
    for i in range(n-1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        else:
            digits[i] = 0

    # If all digits are 9, we need an extra leading 1
    return [1] + digits

